node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all().map(c => c.name);
  const hasPolicy = cols.some(c => /policy|return|rule|term|condition/i.test(c));
  if (hasPolicy) {
    console.log(t.name + ':', cols);
  }
}
// Also check for any policy-related tables
const policyTables = tables.filter(t => /policy|rule|term|condition|config|setting/i.test(t.name));
console.log('\nPolicy-related tables:', policyTables);
"

